class Password {
  #nilai;
  constructor(nilai) {
    this.#nilai = nilai;
  }
  #cukupPanjang() {
    return this.#nilai.length >= 8;
  }
  #adaHurufBesar() {
    return this.#nilai !== this.#nilai.toLowerCase();
  }
  get kekuatan() {
    if (this.#cukupPanjang() && this.#adaHurufBesar()) return "Kuat";
    if (this.#cukupPanjang()) return "Sedang";
    return "Lemah";
  }
}
console.log(new Password("abc").kekuatan);
console.log(new Password("bisangoding").kekuatan);
console.log(new Password("BisaNgoding").kekuatan);

